fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo, switch to the 'Actions' application, and open the 'Explorer' nav item. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Then walk these creation surfaces IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) new-action-panel — click the 'New Action' button in the header (top-right, plus icon); a slide-in titled 'New Action' should appear with an Action Type selector (AI Generated vs Custom cards), a Name field, a Description field, and a Category dropdown. Select an action type, then click 'Create Action' WITHOUT filling the required Name to confirm a validation message blocks the save, then type a name and confirm the validation clears (you do NOT need to complete the create); close/cancel the panel. (2) new-category-panel — in the LEFT category tree panel click the 'new category' affordance (a '+' button in the tree header or next to a category node) and confirm a 'New Category' slide-in opens with a name input (and a parent selector); you may close/cancel it. Keep going until both are done.",
  "startUrl": "http://localhost:4200/app/actions",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "new-action-panel",
      "instruction": "New Action slide-in with type selector + required-field validation",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/actions"
        }
      ],
      "visualCriteria": [
        "Clicking 'New Action' opens a slide-in with an Action Type selector, a Name field, and a Category field; selecting a type highlights it; and attempting to create with a blank required Name surfaces a validation/error message rather than silently saving"
      ]
    },
    {
      "name": "new-category-panel",
      "instruction": "New Category slide-in",
      "visualCriteria": [
        "Clicking the '+' / new-category affordance in the Explorer's left tree panel opens a New Category slide-in with at least a name input field, and it can be closed/cancelled leaving the Explorer functional"
      ]
    }
  ]
}
